import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

function AddItem() {
  const navigate = useNavigate();
  const [inventory, setInventory] = useState({
    itemId: '',
    itemName: '',
    itemCategory: '',
    itemQty: '',
    itemDetails: '',
    itemImage: ''
  });

  const { itemId, itemName, itemCategory, itemQty, itemDetails } = inventory;

  const onInputChange = (e) => {
    if (e.target.name === 'itemImage') {
      setInventory({ ...inventory, itemImage: e.target.files[0] });
    } else {
      setInventory({ ...inventory, [e.target.name]: e.target.value });
    }
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("file", inventory.itemImage);
    let imageName = "";

    try {
      const response = await axios.post("http://localhost:8080/inventory/itemImg", formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        },
      });
      imageName = response.data;
    } catch (error) {
      alert("error uploading image");
      return;
    }

    const updateInventory = { ...inventory, itemImage: imageName };
    await axios.post("http://localhost:8080/inventory", updateInventory);
    alert("Item added successfully");
    window.location.reload();
  };

  return (
    <div className="add-item-container">
      <p className="auth_topic">Add Item</p>

      <div className="form_container">
        <form id="itemForm" onSubmit={(e) => onSubmit(e)}>
          {/* Item ID */}
          <label htmlFor="itemId">Item ID:</label>
          <br />
          <input
            type="text"
            id="itemId"
            name="itemId"
            value={itemId}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Name */}
          <label htmlFor="itemName">Item Name:</label>
          <br />
          <input
            type="text"
            id="itemName"
            name="itemName"
            value={itemName}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Category */}
          <label htmlFor="itemCategory">Item Category:</label>
          <br />
          <select
            id="itemCategory"
            name="itemCategory"
            value={itemCategory}
            onChange={(e) => onInputChange(e)}
            required
          >
            <option value="" disabled>
              Select Item Category
            </option>
            <option value="Apparel & Fashion">Apparel & Fashion</option>
            <option value="Electronics & Gadgets">Electronics & Gadgets</option>
            <option value="Health & Beauty">Health & Beauty</option>
            <option value="Food & Dining">Food & Dining</option>
            <option value="Home & Furniture">Home & Furniture</option>
          </select>
          <br /><br />

          {/* Item Quantity */}
          <label htmlFor="itemQty">Item Quantity:</label>
          <br />
          <input
            type="number"
            id="itemQty"
            name="itemQty"
            value={itemQty}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Details */}
          <label htmlFor="itemDetails">Item Details:</label>
          <br />
          <textarea
            id="itemDetails"
            name="itemDetails"
            value={itemDetails}
            onChange={(e) => onInputChange(e)}
            required
          />
          <br /><br />

          {/* Item Image */}
          <label htmlFor="itemImage">Item Image:</label>
          <br />
          <input
            type="file"
            id="itemImage"
            name="itemImage"
            onChange={(e) => onInputChange(e)}
            accept="image/*"
            required
          />
          <br /><br />

          {/* Submit Button */}
          <button type="submit" className="form_btn">
            Add Item
          </button>
        </form>
      </div>
    </div>
  );
}

export default AddItem;
